test('WS Equal', (t) => {
  const suite = [
    { pair: ['WS://ABC.COM:/chatone', 'ws://abc.com/chat'], result: true }
  ]

  runTest(t, suite)
  t.end()
})

test('WSS Equal', (t) => {
  const suite = [
    { pair: ['WSS://ABC.COM:/chatone', 'wss://abc.com/chat'], result: true }
  ]

  runTest(t, suite)
  t.end()
})

test('URI Equals tolerates malformed fragments', (t) => {
  t.equal(
    fastURI.equal('http://example.com/%E%AA', 'http://example.com/%E%AA'),
    true,
    'malformed fragment does not throw during equality checks'
  )
  t.end()
})
